// 1. Normalize Payload from Meta WhatsApp, YCloud, or Website
const body = $json.body || $json;
let customerPhone = '';
let customerName = 'ग्राहक';
let messageText = '';
let partnerRef = body.partnerRef || null;

// Meta WhatsApp Cloud API
if (body.object === 'whatsapp_business_account') {
  const message = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  const contact = body.entry?.[0]?.changes?.[0]?.value?.contacts?.[0];
  customerPhone = message?.from || '';
  customerName = contact?.profile?.name || 'ग्राहक';
  messageText = message?.text?.body || message?.button?.text || '';
} 
// YCloud WhatsApp Webhook
else if (body.whatsappInboundMessage) {
  customerPhone = body.whatsappInboundMessage.from || '';
  customerName = body.whatsappInboundMessage.senderName || 'ग्राहक';
  messageText = body.whatsappInboundMessage.text?.body || '';
}
// Website or Direct JSON
else {
  customerPhone = body.phone || body.from || '';
  customerName = body.name || body.customerName || 'ग्राहक';
  messageText = body.message || body.text || '';
}

// Classify Intent & Calculate Lead Score
const q = (messageText || '').toLowerCase();
let intent = 'GENERAL_INQUIRY';
let leadScore = 60;
let assignedAgent = 'विक्रय राज (Sales Closer)';

if (q.includes('partner') || q.includes('पार्टनर') || q.includes('kamai') || q.includes('कमाई') || q.includes('work from home')) {
  intent = 'PARTNER_ONBOARDING';
  leadScore = 85;
  assignedAgent = 'सहयोगी (WFH Partner Agent)';
} else if (q.includes('solar') || q.includes('सोलर') || q.includes('78000') || q.includes('सूर्य घर') || q.includes('pump') || q.includes('पंप')) {
  intent = 'HIGH_VALUE_SOLAR';
  leadScore = 95;
  assignedAgent = 'विक्रय राज (Sales Closer)';
} else if (q.includes('kcc') || q.includes('किसान क्रेडिट') || q.includes('pan') || q.includes('पैन') || q.includes('ayushman') || q.includes('आयुष्मान')) {
  intent = 'CITIZEN_SERVICE';
  leadScore = 88;
  assignedAgent = 'विक्रय राज (Sales Closer)';
} else if (q.includes('pvc') || q.includes('photo') || q.includes('print') || q.includes('stamp')) {
  intent = 'PRODUCT_PURCHASE';
  leadScore = 80;
  assignedAgent = 'विक्रय राज (Sales Closer)';
} else {
  intent = 'GENERAL_LOCAL_SERVICE';
  leadScore = 70;
  assignedAgent = 'दिशा (Triage & Qualifier)';
}

return [{
  json: {
    customerPhone,
    customerName,
    messageText,
    partnerRef,
    intent,
    leadScore,
    assignedAgent,
    timestamp: new Date().toISOString()
  }
}];

